entries[337043] = { ["name"] = "Swarming Mist", ["text"] = "Covenant Ability\nInstant\nA heavy mist surrounds you for 8 sec, increasing your Dodge by 10%.\n\nDeals (20% of Attack Power) Shadow damage every 1 sec to enemies within 10 yds. Every time it deals damage you gain 3 Runic Power, up to a maximum of 15 Runic Power. Deals reduced damage beyond 5 targets." }
entries[337044] = { ["name"] = "Sinful Brand", ["text"] = "Covenant Ability\nInstant\nBrand an enemy with the mark of the Venthyr, reducing their melee attack speed by 30%, their casting speed by 30%, and inflicting (338% of Attack Power) Shadow damage over 8 sec.\n\nActivating Metamorphosis applies Sinful Brand to all nearby enemies." }
entries[337045] = { ["name"] = "Ravenous Frenzy", ["text"] = "Covenant Ability\nInstant\nFor 20 sec, Druid spells you cast increase your damage and healing by 2%, and haste by 1%, stacking.\n\nIf you spend 2 sec idle, the Frenzy overcomes you, consuming 1% of your health per stack, stunning you for 1 sec, and ending." }
entries[337046] = { ["name"] = "Flayed Shot", ["text"] = "Covenant Ability\nInstant\nFire a shot at your enemy, dealing (50% of Attack Power) Shadow damage and then causing them to bleed for (112.5% of Attack Power) Shadow damage over 18 sec. Each time Flayed Shot deals damage, you have a 15% chance to gain Flayer's Mark, causing your next Kill Shot to be free, usable on any target regardless of their current health, and deal 25% increased damage." }
entries[337047] = { ["name"] = "Necrotic Breath", ["text"] = "300 yd range\n3 sec cast 5 sec cooldown\nInflicts 40 Shadow damage to all enemies in front of the caster and reduces healing received by 50% for 6 sec." }
entries[337048] = { ["name"] = "Mirrors of Torment", ["text"] = "Covenant Ability\nInstant\nConjure 3 mirrors to torment the enemy for 25 sec. Whenever the target attacks, casts a spell, or uses an ability, a mirror is consumed to inflict (60% of Spell Power) Shadow damage and their movement and cast speed are slowed by 15%. This effect cannot be triggered more often than once per 6 sec.\n\nThe final mirror will instead inflict (151% of Spell Power) Shadow damage to the enemy, Rooting and Silencing them for 4 sec.\n\nWhenever a mirror is consumed [ Arcane : you gain Clearcasting ] [ Fire : your Fire Blast cooldown is reduced by 6 sec ] [ Frost : you gain Brain Freeze ]" }
entries[337049] = { ["name"] = "Chilling Blast", ["text"] = "200 yd range\n3 sec cast\nInflicts 5 Frost damage to enemies within 8 yards and 1 Frost damage every 2 sec, while reducing movement speed by 50% for 8 sec." }
entries[337050] = { ["name"] = "Ashen Hallow", ["text"] = "Covenant Ability\nInstant\nHallow the target area for 30 sec. Enemies in the area suffer up to [(55% of Spell Power) * 30 / 2] Shadow damage, and allies are healed for up to [(36% of Spell Power) * 30 / 2], reduced if there are more than 5 targets.\n\nWithin the Hallow, you may use Hammer of Wrath on any target, and its damage is increased by 100%." }
entries[337051] = { ["name"] = "Mindgames", ["text"] = "Covenant Ability\nInstant\nAssault an enemy's mind, dealing [(300% of Spell Power) * 100 / 100] Shadow damage and briefly reversing their perception of reality.\n\n[ Shadow : For 5 sec, the next [(Shadow spell power * 450 / 100) * (1 + Versatility) * 100 / 100] damage they deal will heal their target, and the next [(Shadow spell power * 450 / 100) * (1 + Versatility) * 100 / 100] healing they deal will damage their target.\n\nReversed damage and healing generate up to 20 Insanity. /\n\nDiscipline, Holy\nFor 5 sec, the next [(Shadow spell power * 450 / 100) * (1 + Versatility) * 100 / 100] damage they deal will heal their target, and the next [(Shadow spell power * 450 / 100) * (1 + Versatility) * 100 / 100] healing they deal will damage their target.\n\nReversed damage and healing restore up to 4% mana. ]" }
entries[337052] = { ["name"] = "Flagellation", ["text"] = "Covenant Ability\nInstant\nLash the target for (50% of Attack Power) Shadow damage, causing each combo point spent within 12 sec to lash for an additional (10% of Attack Power). Dealing damage with Flagellation increases your Haste by 1%, persisting 12 sec after their torment fades." }
entries[337053] = { ["name"] = "Chilling Blast", ["text"] = "200 yd range\nInstant\nInflicts 5 Frost damage to enemies within 8 yards and 1 Frost damage every 2 sec, while reducing movement speed by 50% for 8 sec." }
entries[337054] = { ["name"] = "Chain Harvest", ["text"] = "Covenant Ability\nInstant\nSend a wave of anima at the target, which then jumps to additional nearby targets. Deals (205% of Spell Power) Shadow damage to up to 5 enemies, and restores (315% of Spell Power) health to up to 5 allies.\n\nFor each target critically struck, the cooldown of Chain Harvest is reduced by 5 sec. [ Mastery: Elemental Overload : Generates 3 Maelstrom per target damaged or healed ]" }
entries[337055] = { ["name"] = "Impending Catastrophe", ["text"] = "Covenant Ability\nInstant\nCall forth a cloud of chaotic anima that travels to the target enemy, dealing (25.3% of Spell Power) Shadow damage to enemies in its path. When the anima reaches the target it explodes, inflicting either Curse of Weakness or Curse of Tongues, and dealing (138% of Spell Power) Shadow damage over 12 sec to all nearby enemies." }
entries[337056] = { ["name"] = "Condemn", ["text"] = "Covenant Ability\nInstant\nLearn Condemn, replacing Execute. Condemn deals Shadow damage, can be used on enemies who are above 80% health or below 20% health, and weakens the target preventing some of the damage they would deal to you." }
