entries[337430] = { ["name"] = "Death's Due", ["text"] = "Covenant Ability\nInstant\nCorrupts the targeted ground, causing [(5.4054% of Attack Power) * 11] Shadow damage over 10 sec to targets within the area.\n\nBlood, Unholy\nWhile you remain within the area, your [Necrotic Strike and] [ Blood : Heart Strike will hit up to 0 additional targets and inflict Death's Due for 12 sec ][Scourge Strike will hit up to 7 enemies near the target and inflict Death's Due for 12 sec.] [\nWhile you remain within the area, your Obliterate will hit up to 1 additional target and inflict Death's Due for 12 sec.]\nDeath's Due reduces damage enemies deal to you by 2%, up to a maximum of 8% and their power is transferred to you as an equal amount of Strength." }
entries[337431] = { ["name"] = "The Hunt", ["text"] = "Covenant Ability\nInstant\nCharge to your target, striking them for (455% of Attack Power) Nature damage, rooting them in place for 1.5 sec and inflicting (227.7% of Attack Power) Nature damage over 6 sec to up to 5 enemies in your path.\n\nThe pursuit invigorates your soul, healing you for [ Havoc : 25% /\n\nVengeance\n50% ] of the damage you deal to your Hunt target for 30 sec." }
entries[337433] = { ["name"] = "Convoke the Spirits", ["text"] = "Covenant Ability\nInstant\nCall upon the Night Fae for an eruption of energy, channeling a rapid flurry of 16 Druid spells and abilities over 4 sec.\n\nYou will cast Wild Growth, Swiftmend, Moonfire, Wrath, Regrowth, Rejuvenation, Rake, and Thrash on appropriate nearby targets, favoring your current shapeshift form." }
entries[337434] = { ["name"] = "Wild Spirits", ["text"] = "Covenant Ability\nInstant\nEvoke the energy of Wild Spirits at the target location, dealing (25% of Attack Power) Nature damage and apply Wild Mark to all enemy targets within the area for 15 sec.\n\nWhile the Wild Spirits are active, each damaging ability you or your pet use against a target in the area will strike up to 5 nearby targets for (38.5% of Attack Power) Nature damage." }
entries[337435] = { ["name"] = "Shifting Power", ["text"] = "Covenant Ability\nInstant\nDraw power from the ground beneath, dealing [(60.996% of Spell Power) * 4] Nature damage over 4 sec to enemies within 18 yds.\n\nWhile channeling, your Mage ability cooldowns are reduced by 10 sec over 4 sec." }
entries[337436] = { ["name"] = "Faeline Stomp", ["text"] = "Covenant Ability\nInstant\nBrewmaster\nStrike the ground fiercely to expose a faeline for 30 sec, dealing (40% of Attack Power) Nature damage to up to 5 enemies, and restores (91% of Spell Power) health to up to 5 allies within 30 yds caught in the faeline. Stagger is 5% more effective for 8 sec against enemies caught in the faeline.\n\nYour abilities have a 6% chance of resetting the cooldown of Faeline Stomp while fighting on a faeline.\n\nMistweaver\nStrike the ground fiercely to expose a faeline for 30 sec, dealing (40% of Attack Power) Nature damage to up to 5 enemies, and restores (91% of Spell Power) health to up to 5 allies within 30 yds caught in the faeline. Up to 5 allies caught in the faeline are healed with an Essence Font bolt.\n\nYour abilities have a 6% chance of resetting the cooldown of Faeline Stomp while fighting on a faeline.\n\nWindwalker\nStrike the ground fiercely to expose a faeline for 30 sec, dealing (40% of Attack Power) Nature damage to up to 5 enemies, and restores (91% of Spell Power) health to up to 5 allies within 30 yds caught in the faeline. Up to 5 enemies caught in the faeline suffer an additional (65% of Attack Power) damage.\n\nYour abilities have a 6% chance of resetting the cooldown of Faeline Stomp while fighting on a faeline." }
entries[337437] = { ["name"] = "Arcane Barrage" }
entries[337438] = { ["name"] = "Blessing of Summer", ["text"] = "Covenant Ability\nInstant\nBless an ally for 30 sec, causing their attacks to have a 40% chance to deal 30% additional damage as Holy.\n\nBlessing of the Seasons: Turns to Autumn after use." }
entries[337439] = { ["name"] = "Fae Guardians", ["text"] = "Covenant Ability\nInstant\nCall forth three faerie guardians to attend your targets for 20 sec.\n\nWrathful Faerie : Any direct attacks against the target restore 0.5% Mana or 3 Insanity. Follows your Shadow Word: Pain.\n\nGuardian Faerie : Reduces damage taken by 20%. Follows your Power Word: Shield.\n\nBenevolent Faerie : Increases the cooldown recovery rate of your target's major ability by 100%. Follows your [ Holy : Flash Heal /\n\nDiscipline, Shadow\nShadow Mend ]" }
entries[337440] = { ["name"] = "Sepsis", ["text"] = "Covenant Ability\nInstant\nInfect the target's blood, dealing (162.89% of Attack Power) Nature damage over 10 sec. If the target survives its full duration, they suffer an additional (77.5667% of Attack Power) damage and you gain 1 use of any Stealth ability for 5 sec.\n\nCooldown reduced by 30 sec if Sepsis does not last its full duration.\n\nAwards 1 combo point." }
entries[337441] = { ["name"] = "Fae Transfusion", ["text"] = "Covenant Ability\nInstant\nTransfer the life force of up to 4 enemies in the targeted area, dealing [((117.5% of Spell Power) * 3 / 0.5) + (117.5% of Spell Power)] Nature damage evenly split to each enemy target over 3 sec. [ Enhancement : Fully channeling Fae Transfusion generates 3 stacks of Maelstrom Weapon ]\nPressing Fae Transfusion again within 20 sec will release 60% of all damage from Fae Transfusion, healing up to 4 allies within 20 yds." }
