entries[337444] = { ["name"] = "Soul Rot", ["text"] = "Covenant Ability\nInstant\nWither away all life force of your current target and up to 3 additional targets nearby, causing your primary target to suffer [(100% of Spell Power) * 2] Nature damage and secondary targets to suffer (100% of Spell Power) Nature damage over 8 sec.\n\nFor the next 8 sec, casting Drain Life will cause you to also Drain Life from any enemy affected by your Soul Rot, and Drain Life will not consume any mana." }
entries[337445] = { ["name"] = "Leap", ["text"] = "30 yd range\nInstant\nLeap through the air, dealing 100 damage to nearby enemies when you land." }
entries[337446] = { ["name"] = "Ancient Aftershock", ["text"] = "Covenant Ability\nInstant\nUnleash a wave of anima, dealing (220% of Attack Power) Nature damage to up to 5 enemies and knocking them down for 1.5 sec.\n\nThe ground will continue to expel anima, dealing [4 * (35% of Attack Power)] Nature damage to up to 5 enemies and generating 16 Rage per enemy over 12 sec. Every 3 sec, targets are briefly knocked down." }
