entries[337470] = { ["name"] = "Token of Appreciation", ["text"] = "100 yd range\nInstant\nGrant a shield that absorbs [Attack Power * 1.5 * (1 + Versatility)] damage to allies who aid you with healing or beneficial magic effects. You will only shield each ally once every 20 sec." }
