entries[337473] = { ["name"] = "Tear of Morning", ["text"] = "Runecarving Power\nCasting Vivify or Enveloping Mist on a target with Renewing Mist has a 10% chance to spread the Renewing Mist to another target.\n\nYour Vivify healing through Renewing Mist is increased by 20% and your Enveloping Mist also heals allies with Renewing Mist for 20% of its healing.\nRunecarve on: Head, Waist\nSource: Raid Drop: Sludgefist\nRequires: Monk (Mistweaver)" }
entries[337474] = { ["name"] = "Granite Eruption", ["text"] = "Instant\nGrashaal's skin hardens, reducing all damage taken by 95% until removed." }
entries[337476] = { ["name"] = "Clouded Focus", ["text"] = "Instant\nHealing with Enveloping Mists or Vivify while channeling Soothing Mists increases their healing done by 20% and reduces their mana cost by 20%. Stacks up to 3 times.\n\nWhen your Soothing Mists channel ends, this effect is cancelled." }
entries[337477] = { ["name"] = "X'anshi, Return of Archbishop Benedictus", ["text"] = "Runecarving Power\nAfter Spirit of Redemption expires, you will revive at up to 100% health, based on your effectiveness during Spirit of Redemption. After reviving, you cannot benefit from Spirit of Redemption for 10 min.\nRunecarve on: Legs, Back\nSource: World Boss Drop: Valinor, the Light of Eons\nRequires: Priest (Holy)" }
entries[337478] = { ["name"] = "Splintering Shoots", ["text"] = "Instant\nThe Splinterbark Nightmare bursts with natural energy, launching splinters of life and death at nearby locations." }
