entries[337481] = { ["name"] = "Xuen's Battlegear", ["text"] = "Runecarving Power\nRising Sun Kick critical strikes reduce the cooldown of Fists of Fury by 5.0 sec.\n\nWhen Fists of Fury ends, the critical strike chance of Rising Sun Kick is increased by 40% for 5 sec.\nRunecarve on: Chest, Back\nSource: Dungeon Drop: Kryxis the Voracious\nRequires: Monk (Windwalker)" }
entries[337482] = { ["name"] = "Pressure Point", ["text"] = "Instant\nRising Sun Kick critical strikes reduce the cooldown of Fists of Fury by 5.0 sec.\n\nWhen Fists of Fury ends, the critical strike chance of Rising Sun Kick is increased by 40% for 5 sec." }
entries[337483] = { ["name"] = "Jade Ignition", ["text"] = "Runecarving Power\nWhenever you deal damage to a target with Fists of Fury, you gain a stack of Chi Energy up to a maximum of 30 stacks.\n\nUsing Spinning Crane Kick will cause the energy to detonate in a Chi Explosion, dealing (65% of Attack Power) damage to all enemies within 8 yards. The damage is increased by 5% for each stack of Chi Energy.\nRunecarve on: Legs, Back\nSource: Drop: Torghast, Tower of the Damned. The Soulforges, Layer 3+\nRequires: Monk (Windwalker)" }
